after.hourglass/gaps.py:
"""Find the stretches of opening hours left uncovered."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans
from hourglass.errors import OutsideHoursError


def check_inside(
    spans: Iterable[Span], opening: Span
) -> None:
    """Raise OutsideHoursError for a span past the hours."""
    for span in spans:
        if span.start < opening.start:
            raise OutsideHoursError(format_span(span))
        if span.end > opening.end:
            raise OutsideHoursError(format_span(span))


def find_gaps(
    spans: Iterable[Span], opening: Span
) -> List[Span]:
    """Uncovered stretches of the opening span, in order."""
    merged = merge_spans(spans)
    starts = [item.start for item in merged] + [opening.end]
    ends = [opening.start] + [item.end for item in merged]
    pairs = zip(ends, starts)
    return [
        Span(*pair) for pair in pairs if pair[0] < pair[1]
    ]


def gap_label(gap: Span) -> str:
    return f"gap {format_span(gap)} ({gap.minutes} min)"


def uncovered_labels(
    spans: Iterable[Span], opening: Span
) -> List[str]:
    """One text label per uncovered stretch."""
    spans = list(spans)
    check_inside(spans, opening)
    gaps = find_gaps(spans, opening)
    return [gap_label(gap) for gap in gaps]

after.tests/test_gaps.py:
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import uncovered_labels
from hourglass.errors import OutsideHoursError


def labels(worked, opening="09:00-17:00"):
    spans = [parse_span(text) for text in worked]
    return uncovered_labels(spans, parse_span(opening))


class GapTests(unittest.TestCase):
    def test_gap_between_spans(self):
        result = labels(["09:00-12:00", "13:00-17:00"])
        expect = ["gap 12:00-13:00 (60 min)"]
        self.assertEqual(result, expect)

    def test_full_coverage_has_no_gaps(self):
        self.assertEqual(labels(["09:00-17:00"]), [])

    def test_overlaps_do_not_make_gaps(self):
        worked = ["09:00-13:00", "12:00-17:00"]
        self.assertEqual(labels(worked), [])

    def test_nobody_working(self):
        self.assertEqual(
            labels([]), ["gap 09:00-17:00 (480 min)"]
        )

    def test_gaps_at_both_ends(self):
        self.assertEqual(
            labels(["10:00-16:00"]),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 16:00-17:00 (60 min)"
            ]
        )

    def test_touching_spans_leave_no_gap(self):
        worked = ["09:00-12:00", "12:00-17:00"]
        self.assertEqual(labels(worked), [])

    def test_unsorted_input(self):
        worked = ["14:00-17:00", "09:00-12:00"]
        self.assertEqual(
            labels(worked), ["gap 12:00-14:00 (120 min)"]
        )


class OutsideHoursTests(unittest.TestCase):
    def test_starts_before_opening(self):
        with self.assertRaises(OutsideHoursError):
            labels(["08:00-12:00"])

    def test_ends_after_closing(self):
        with self.assertRaises(OutsideHoursError):
            labels(["13:00-17:30"])
